-- Run only in the disposable database built by scripts/rehearse-solo.mjs.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT plan(23);
SELECT results_eq('select * from public.profiles order by id','select * from solo_before.profiles order by id','Profiles preserved');
SELECT results_eq('select * from public.matches order by id','select * from solo_before.matches order by id','Matches preserved');
SELECT results_eq('select * from public.match_players order by id','select * from solo_before.players order by id','Participants preserved');
SELECT results_eq('select * from public.league_nights order by id','select * from solo_before.nights order by id','Nights preserved');
SELECT is((SELECT count(*) FROM pg_class WHERE oid IN ('public.solo_sessions'::regclass,'public.solo_games'::regclass,'public.solo_preferences'::regclass) AND relrowsecurity),3::bigint,'All public solo tables have RLS');
SELECT ok(NOT has_table_privilege('authenticated','public.solo_games','INSERT,UPDATE,DELETE'),'Authenticated role cannot write directly');
SELECT ok(NOT has_function_privilege('anon','public.rdd_solo_write(uuid,jsonb)','EXECUTE'),'Anonymous writes denied');
SELECT ok(NOT has_table_privilege('authenticated','rdd_private.solo_operations','SELECT'),'Replay log is private');
SELECT is((SELECT count(*) FROM pg_proc WHERE proname IN ('rdd_solo_write','rdd_solo_profile','rdd_solo_night','rdd_set_solo_visibility') AND prosecdef AND proconfig=ARRAY['search_path=""']),4::bigint,'Definers have fixed empty search paths');
INSERT INTO auth.users(id) VALUES('00000000-0000-4000-8000-000000000098') ON CONFLICT DO NOTHING;
INSERT INTO public.league_members(user_id) VALUES('00000000-0000-4000-8000-000000000099'),('00000000-0000-4000-8000-000000000098');
CREATE FUNCTION pg_temp.payload() RETURNS jsonb LANGUAGE sql AS $p$
 SELECT '{"action":"save","submitted_by":"00000000-0000-4000-8000-000000000099","id":"00000000-0000-4000-8000-000000000091","session_id":"00000000-0000-4000-8000-000000000092","expected_revision":null,"played_at":"2026-03-01T23:00:00Z","completed_at":null,"timezone":"America/New_York","game_type":"501","board_type":"Steel Tip","preset":"501-double-v1","status":"completed","score":60,"score_unit":"3DA","raw_total":501,"darts":30,"include_in_stats":true,"night_id":null,"share_with_night":false,"notes":"Private fixture note","location":"Private location"}'::jsonb;
$p$;
CREATE FUNCTION pg_temp.fail_replay() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Injected replay failure' USING ERRCODE='XX000'; END $$;
CREATE TRIGGER solo_fault BEFORE INSERT ON rdd_private.solo_operations FOR EACH ROW EXECUTE FUNCTION pg_temp.fail_replay();
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000099"}',true);
SELECT throws_ok($q$SELECT public.rdd_solo_write('00000000-0000-4000-8000-000000000093',pg_temp.payload())$q$,'XX000','Injected replay failure','Replay failure aborts save');
RESET ROLE;
SELECT ok((SELECT count(*) FROM public.solo_games)=0 AND (SELECT count(*) FROM public.solo_sessions)=0 AND (SELECT count(*) FROM rdd_private.solo_operations)=0,'Session, game and operation all rolled back');
DROP TRIGGER solo_fault ON rdd_private.solo_operations;
SET LOCAL ROLE authenticated;
SELECT is(public.rdd_solo_write('00000000-0000-4000-8000-000000000093',pg_temp.payload())->>'revision','1','Same operation succeeds after rollback');
SELECT is(public.rdd_solo_write('00000000-0000-4000-8000-000000000093',pg_temp.payload())->>'replayed','true','Exact retry returns outcome');
SELECT throws_ok($q$SELECT public.rdd_solo_write('00000000-0000-4000-8000-000000000093',pg_temp.payload()||'{"score":70}'::jsonb)$q$,'PT409',null,'Changed retry rejected');
SELECT throws_ok($q$SELECT public.rdd_solo_write('00000000-0000-4000-8000-000000000094',pg_temp.payload())$q$,'40001',null,'Stale create cannot overwrite');
SELECT is((public.rdd_solo_profile('00000000-0000-4000-8000-000000000099')->0->>'raw_total_sum')::numeric,501::numeric,'Raw aggregate preserves net points');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000098"}',true);
SELECT is((SELECT count(*) FROM public.solo_games),0::bigint,'Other account sees no private history');
SELECT is(public.rdd_solo_profile('00000000-0000-4000-8000-000000000099'),NULL::jsonb,'Profile private by default');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000099"}',true);
SELECT public.rdd_set_solo_visibility(true);
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000098"}',true);
SELECT ok(public.rdd_solo_profile('00000000-0000-4000-8000-000000000099')::text NOT LIKE '%Private%' AND public.rdd_solo_profile('00000000-0000-4000-8000-000000000099')::text NOT LIKE '%00000000-%','Consented summary contains no private detail or identifiers');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000099"}',true);
SELECT is(public.rdd_solo_write('00000000-0000-4000-8000-000000000095','{"action":"delete","submitted_by":"00000000-0000-4000-8000-000000000099","id":"00000000-0000-4000-8000-000000000091","expected_revision":1}'::jsonb)->>'deleted','true','Delete confirmed');
SELECT is(public.rdd_solo_write('00000000-0000-4000-8000-000000000093',pg_temp.payload())->>'deleted','true','Old save replay cannot resurrect deleted game');
RESET ROLE;
SELECT results_eq('select * from public.matches order by id','select * from solo_before.matches order by id','Competitive results unchanged after solo writes');
SELECT results_eq('select * from public.match_players order by id','select * from solo_before.players order by id','Competitive participants unchanged after solo writes');
SELECT * FROM finish();
ROLLBACK;
